import{_ as t,a as o,c as a,ac as i}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 74 Out of the limelight","description":"学习 定语从句与指代，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 74 Out of the limelight","description":"学习 定语从句与指代，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 定语从句与指代，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 73 The record-holder","link":"/life/english/new-concept/book-2/unit-04/lesson-073"},"next":{"text":"第二册：实践与进步 · Lesson 75 SOS","link":"/life/english/new-concept/book-2/unit-04/lesson-075"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 73 The record-holder","link":"/life/english/new-concept/book-2/unit-04/lesson-073"},"next":{"text":"第二册：实践与进步 · Lesson 75 SOS","link":"/life/english/new-concept/book-2/unit-04/lesson-075"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-04/lesson-074.md","filePath":"life/english/new-concept/book-2/unit-04/lesson-074.md"}'),r={name:"life/english/new-concept/book-2/unit-04/lesson-074.md"};function n(s,e,l,h,d,c){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="第二册-实践与进步-·-lesson-74-out-of-the-limelight" tabindex="-1">第二册：实践与进步 · Lesson 74 Out of the limelight <a class="header-anchor" href="#第二册-实践与进步-·-lesson-74-out-of-the-limelight" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 74 Out of the limelight&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元 4</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>公众人物在休息时仍可能被认出，隐私需求需要礼貌表达；练习关系从句筛选对象。本课的语言观察是：who recognised her 限定是哪位游客，关系代词在从句中作主语不能省略。若改为 she recognised，缺的是宾语，结构会不同。完成学习后，请写一段尊重隐私的偶遇，使用 who 从句说明人物身份。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>famous</td><td>/ˈfeɪməs/</td><td>adj.</td><td>出名的</td><td>a famous actor</td></tr><tr><td>privacy</td><td>/ˈprɪvəsi/</td><td>n.</td><td>隐私</td><td>respect privacy</td></tr><tr><td>reporter</td><td>/rɪˈpɔːtə/</td><td>n.</td><td>记者</td><td>a local reporter</td></tr><tr><td>recognise</td><td>/ˈrekəɡnaɪz/</td><td>v.</td><td>认出</td><td>recognise a face</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>keep a secret — 保守秘密</li><li>leave somebody alone — 不打扰某人</li></ul><h2 id="语法讲解-定语从句与指代" tabindex="-1">语法讲解：定语从句与指代 <a class="header-anchor" href="#语法讲解-定语从句与指代" aria-label="Permalink to &quot;语法讲解：定语从句与指代&quot;">​</a></h2><p>定语从句跟在被修饰名词之后，用 who、which、that 等连接并在从句内承担成分。限制性从句帮助确定“是哪一个”，非限制性从句用逗号补充信息。关系代词作宾语时，在限制性从句中常可省略；作主语时不能省略。先确定先行词，再检查从句缺主语、宾语还是状语，避免同时保留一个多余的 he、it 或 them。本课应用：who recognised her 限定是哪位游客，关系代词在从句中作主语不能省略。若改为 she recognised，缺的是宾语，结构会不同。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The visitor who recognised the actor kept her secret.</p></blockquote><p>认出演员的那位游客替她保守了秘密。</p><p>who 指 the visitor 并作 recognised 的主语；kept 是主句谓语，her 指前文 actor。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>The visitor who recognised the actor smiled. 中 who 作 recognised 的主语，意思是“认出演员的那位游客笑了”。The visitor who he recognised smiled. 也合法：he 作从句主语，who 作宾语，意思是“他认出的那位游客笑了”。若要表达前一种意思，不能写 The visitor who he recognised the actor smiled.；从句已有主语 he 和宾语 the actor，再加 who 会造成成分重复。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>在限制性 who 从句前不作长停顿，让 visitor who recognised 连成识别单位。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The visitor who recognised the actor kept her secret. They spoke briefly about the town. Nobody asked for a photograph.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写一段尊重隐私的偶遇，使用 who 从句说明人物身份。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：who 指 the visitor 并作 recognised 的主语；kept 是主句谓语，her 指前文 actor。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：The visitor who recognised the actor smiled. 中 who 作 recognised 的主语，意思是“认出演员的那位游客笑了”。The visitor who he recognised smiled. 也合法：he 作从句主语，who 作宾语，意思是“他认出的那位游客笑了”。若要表达前一种意思，不能写 The visitor who he recognised the actor smiled.；从句已有主语 he 和宾语 the actor，再加 who 会造成成分重复。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>能否省略 The visitor who recognised her 中的 who？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不能。</p><p><strong>解析：</strong> who 是定语从句主语，不能像宾语关系代词那样省略。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>有没有人要求合影？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> No.</p><p><strong>解析：</strong> 最后一句明确 nobody，不是说没有人认出演员。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>合并：The visitor recognised her. The visitor smiled。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The visitor who recognised her smiled.</p><p><strong>解析：</strong> 用 who 替代第二次出现的同一主语。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：定语从句与指代。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-073">上一课</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-04/lesson-075">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const g=t(r,[["render",n]]);export{u as __pageData,g as default};
